function cloneWeaponVfxProfile(profile) {
  if (typeof profile === "string") return profile;
  if (!profile || typeof profile !== "object" || Array.isArray(profile)) return null;
  const out = { ...profile };
  if (Array.isArray(profile.alphaStops)) {
